, 40377417, 3546770051172786, 3493131183983543, 1155199831, 3546928893659328, 1700344493, 493669304, 3546737448847514, 3537111630220019, 308070494, 388824674, 334299, 3546929885612063, 3546390955297692, 698957, 3546873228953627, 3546800591997446, 103701980, 3706961918953897, 13870061, 288563414, 395421158, 129128742, 38216891, 3493128180861721, 3546637020432882, 1427659913, 432709515, 3690992297314433, 3546882309622281, 12610294, 10850097, 3546877796551210, 629923042, 3546968947165842, 107855980, 3546562510719482, 1074836492, 361542249, 10548861, 3546623401527958, 592056798, 3690987985570021, 3546692349594512, 3546914687551975, 1610203585, 3546637928499654, 3493114452904573, 3546813460121933, 110944867, 3537118573890235, 3546881349126250, 275529727, 3546642934401434, 40116949, 3706926212844144, 543976958, 529452132, 281101891, 3546733130811509, 3706946129496658, 526903482, 23605071, 3546605003213432, 3690980926556811, 1932117607, 3690986043607950, 3690981243226451, 13611123, 368005981, 510811425, 581845812, 3546677690502084, 3546964725599103, 629545145, 3494376701429985, 477293262, 61214429, 391945825, 1053088039, 3706968428514163, 3632300321409668, 3537108773898362, 524692685, 693000149, 327295089, 539776572, 415211722, 3706924335892949, 3690971141245905)
      AND a.pubtime >= DATE_SUB(CURRENT_DATE, 30)
),
charge_revenue AS (
    SELECT
        avid,
        SUM(order_amt) AS total_gmv,
        COUNT(DISTINCT mid) AS charge_users
    FROM bili_ogv.dwb_trd_main_chrg_order_p24h_ascrb_i_d
    WHERE log_date BETWEEN b_current_datedelta('-30') AND b_current_datedelta('-1')
    and avid in (select DISTINCT avid from arch_info)
    GROUP BY 1
),
play_stats AS (
    SELECT
        avid,
        SUM(vv) AS total_vv,
        SUM(play_buvid_uv) AS total_play_uv
    FROM b_dwb.dwb_ctnt_arch_play_avid_vv_vt_i_d
    WHERE log_date BETWEEN b_current_datedelta('-30') AND b_current_datedelta('-1')
    and avid in (select DISTINCT avid from arch_info)
    GROUP BY 1
),
asr_content AS (
    SELECT
        aid AS avid,
        MIN(asr_data) AS asr_data
    FROM ai.llm_asr_filter_full
    WHERE log_date = b_current_datedelta('-1')
      AND aid IN (SELECT distinct avid FROM arch_info)
    GROUP BY 1
)
SELECT
    `UP主ID`, `UP主昵称`, `稿件ID`, `稿件标题`, `稿件类型`, `播放页`,
    `发布时间`, `一级分区`, `二级分区`, `tag`, `稿件近30日GMV`,
    `稿件近30日播放量`, `稿件近30日ECPVV`, `稿件近30日充电人数`,
    `稿件近30日转化率`, asr_data
FROM (
    SELECT
        a.up_id AS `UP主ID`,
        a.uname AS `UP主昵称`,
        a.avid as `稿件ID`,
        a.title AS `稿件标题`,
        a.arch_type AS `稿件类型`,
        CONCAT('https://www.bilibili.com/video/av', a.avid) AS `播放页`,
        a.pubtime AS `发布时间`,
        a.tid_name AS `一级分区`,
        a.sub_tid_name AS `二级分区`,
        a.tag as `tag`,
        ROUND(COALESCE(b.total_gmv, 0) / 1000.0, 2) AS `稿件近30日GMV`,
        COALESCE(c.total_vv, 0) AS `稿件近30日播放量`,
        ROUND(COALESCE(b.total_gmv, 0) / NULLIF(c.total_vv, 0) * 1000 / 1000.0, 2) AS `稿件近30日ECPVV`,
        COALESCE(b.charge_users, 0) AS `稿件近30日充电人数`,
        ROUND(COALESCE(b.charge_users, 0) / NULLIF(c.total_play_uv, 0), 4) AS `稿件近30日转化率`,
        SUBSTRING(d.asr_data, 1, 1000) AS asr_data,
        ROW_NUMBER() OVER (PARTITION BY a.up_id ORDER BY b.total_gmv DESC) AS rn
    FROM arch_info a
    LEFT JOIN charge_revenue b ON a.avid = b.avid
    LEFT JOIN play_stats c ON a.avid = c.avid
    LEFT JOIN asr_content d ON a.avid = d.avid
    WHERE b.total_gmv > 0
) t
WHERE rn <= 5  --只保留top5稿件
ORDER BY `稿件近30日GMV` DESC